<?php
declare(strict_types=1);
require_once __DIR__ . '/../bootstrap/app.php';
$context = balanco_require_access();
if (!balanco_can_process()) { balanco_flash('error', 'Seu perfil não possui a permissão de processar balanço.'); header('Location: ' . balanco_url()); exit; }
$id = (int) ($_GET['t066_id'] ?? 0);
global $g;
$company = (int) $g['empresaAtual'];
$sql = "SELECT T066_Id, T066_D009_Id, T066_D004_Id, T066_Quantidade_Estoque, T066_Quantidade_Estoque_Liquido, T066_Flag_Balanco, T066_C007_Id_Marcou_Balanco, T066_Data_Balanco, D009_Quantidade_Estoque, D009_Quantidade_Estoque_Liquido, D009_Quantidade_Pedido(D009_Id, 1) AS D009_Quantidade_Pedido, D009_Quantidade_Pedido_Por_Locacao(D009_Id, T066_Id) AS T066_Quantidade_Pedido, COALESCE((SELECT SUM(T006_Empresa.T006_Quantidade_Separacao) FROM T006 AS T006_Empresa INNER JOIN T005 AS T005_Empresa ON T005_Empresa.T005_Id=T006_Empresa.T006_T005_Id LEFT JOIN T008 AS T008_Empresa ON T008_Empresa.T008_T006_Id=T006_Empresa.T006_Id WHERE T006_Empresa.T006_D009_Id=D009_Id AND T005_Empresa.T005_Flag_Status IN ('2', '10', '3') AND IFNULL(T005_Empresa.T005_T005_Id_Agrupado, 0)=0 AND T006_Empresa.T006_Flag_Status!='3' AND T008_Empresa.T008_Id IS NULL), 0) AS D009_Quantidade_Separado, COALESCE((SELECT SUM(T238_Locacao.T238_Quantidade_Separacao) FROM T238 AS T238_Locacao INNER JOIN T006 AS T006_Locacao ON T006_Locacao.T006_Id=T238_Locacao.T238_T006_Id INNER JOIN T005 AS T005_Locacao ON T005_Locacao.T005_Id=T238_Locacao.T238_T005_Id WHERE T006_Locacao.T006_D009_Id=D009_Id AND T238_Locacao.T238_T066_Id=T066_Id AND T005_Locacao.T005_Flag_Status IN ('2', '10', '3') AND IFNULL(T005_Locacao.T005_T005_Id_Agrupado, 0)=0 AND T006_Locacao.T006_Flag_Status!='3'), 0) AS T066_Quantidade_Separado, D004_Local, D001_Id, D001_Codigo_Produto, D001_Codigo_Barras, D001_Descricao_Produto, D037_Unidade, D082_Marca, C007_Primeiro_Nome FROM T066 LEFT JOIN D009 ON D009_Id=T066_D009_Id LEFT JOIN D049 ON D049_Id=D009_D049_Id LEFT JOIN D001 ON D001_Id=D049_D001_Id LEFT JOIN D004 ON D004_Id=T066_D004_Id LEFT JOIN D037 ON D037_Id=D001_D037_Id LEFT JOIN D082 ON D082_Id=D049_D082_Id LEFT JOIN C007 ON C007_Id=T066_C007_Id_Marcou_Balanco WHERE T066_Id='{$id}' AND D009_C004_Id='{$company}' AND D004_C004_Id='{$company}' LIMIT 1";
$query = mysqli_query($g['conexaoBanco'], $sql);
$item = $query ? mysqli_fetch_assoc($query) : null;
if (!$item) { balanco_flash('error', 'Registro de produto por locação não encontrado.'); header('Location: ' . balanco_url()); exit; }
$other = $item['T066_Flag_Balanco'] === 'S' && (int) $item['T066_C007_Id_Marcou_Balanco'] !== $context['user_id'];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    balanco_require_csrf();
    $action = (string) ($_POST['action'] ?? '');
    if ($action === 'finalize_balance') {
        try { $result = balanco_finalize_t066($id, (string) ($_POST['quantity'] ?? ''), $context); }
        catch (Throwable $e) { $result = ['status' => 'error', 'message' => 'Não foi possível efetivar o balanço: ' . $e->getMessage()]; }
        if ($result['status'] === 'completed') {
            balanco_flash('success', 'Balanço efetivado. Bipe o próximo produto.');
            header('Location: ' . balanco_url()); exit;
        }
        balanco_flash('error', $result['message'] ?? 'Não foi possível efetivar o balanço.');
        header('Location: ' . balanco_url('contar.php?t066_id=' . $id)); exit;
    }
    if ($action === 'abandon_count') {
        try { $result = balanco_abandon_t066($id, $context); }
        catch (Throwable $e) { balanco_flash('error', $e->getMessage()); header('Location: ' . balanco_url('contar.php?t066_id=' . $id)); exit; }
        balanco_flash($result['status'] === 'released' ? 'success' : 'error', $result['status'] === 'released' ? 'Contagem abandonada; marcação liberada.' : 'A marcação não pertence a este usuário.');
        header('Location: ' . balanco_url('locacoes.php?d009_id=' . (int) $item['T066_D009_Id'])); exit;
    }
    balanco_flash('error', 'Solicitação de contagem inválida.');
    header('Location: ' . balanco_url('contar.php?t066_id=' . $id)); exit;
}
if ($other) { balanco_flash('error', 'Este item está sendo contado por ' . ($item['C007_Primeiro_Nome'] ?: 'outro usuário') . '.'); header('Location: ' . balanco_url()); exit; }
$own = $item['T066_Flag_Balanco'] === 'S' && (int) $item['T066_C007_Id_Marcou_Balanco'] === $context['user_id'];
if (!$own) { balanco_flash('error', 'Entre na contagem pela seleção da locação para marcar este item.'); header('Location: ' . balanco_url('locacoes.php?d009_id=' . (int) $item['T066_D009_Id'])); exit; }
$currentStock = balanco_format_quantity($item['T066_Quantidade_Estoque'], 2);
$companyPhysicalStock = (float) $item['D009_Quantidade_Estoque'];
$companyLiquidStock = (float) $item['D009_Quantidade_Estoque_Liquido'];
$companyOrderStock = (float) $item['D009_Quantidade_Pedido'];
$companySeparatedStock = (float) $item['D009_Quantidade_Separado'];
$locationPhysicalStock = (float) $item['T066_Quantidade_Estoque'];
$locationLiquidStock = (float) $item['T066_Quantidade_Estoque_Liquido'];
$locationOrderStock = (float) $item['T066_Quantidade_Pedido'];
$locationSeparatedStock = (float) $item['T066_Quantidade_Separado'];
balanco_header('Contar item', $context);
?>
