    <button class="stock-overview" type="button" id="open-stock-overview" aria-haspopup="dialog" aria-label="Abrir detalhes da posição do estoque"><span class="stock-overview__label">Posição do estoque</span><span class="stock-overview__action" title="Ver posição completa" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" stroke-width="2"/><path d="M12 10v6m0-9h.01" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></span><span class="stock-overview__liquids"><span class="stock-overview__row"><strong>Empresa</strong><span>Físico <b id="stock-company-physical-summary"><?php echo balanco_h(balanco_format_quantity($companyPhysicalStock, 2)); ?></b></span><span>Líquido <b class="stock-overview__liquid" id="stock-company-liquid-summary"><?php echo balanco_h(balanco_format_quantity($companyLiquidStock, 2)); ?></b></span></span><span class="stock-overview__row"><strong>Locação</strong><span>Físico <b id="stock-location-physical-summary"><?php echo balanco_h(balanco_format_quantity($locationPhysicalStock, 2)); ?></b></span><span>Líquido <b class="stock-overview__liquid" id="stock-location-liquid-summary"><?php echo balanco_h(balanco_format_quantity($locationLiquidStock, 2)); ?></b></span></span></span></button>
    <dialog class="confirm-dialog stock-overview-dialog" id="stock-overview-dialog"><h2>Posição do estoque</h2><p class="stock-overview-dialog__updated" id="stock-overview-updated" aria-live="polite">Atualizando posição…</p><div class="stock-overview__content" aria-label="Posição de estoque">
        <div class="stock-overview__group"><div class="stock-overview__title">Item na empresa</div><dl class="stock-overview__metrics"><div><dt>Físico</dt><dd class="stock-overview__physical" id="stock-company-physical"><?php echo balanco_h(balanco_format_quantity($companyPhysicalStock, 2)); ?></dd></div><div><dt title="Pedidos">Ped.</dt><dd class="stock-overview__reserved" id="stock-company-orders"><?php echo balanco_h(balanco_format_quantity($companyOrderStock, 2)); ?></dd></div><div><dt title="Estoque físico menos pedidos">Líq.</dt><dd class="stock-overview__liquid" id="stock-company-liquid"><?php echo balanco_h(balanco_format_quantity($companyLiquidStock, 2)); ?></dd></div><div><dt title="Pedidos nos status Separando, Conferindo e Emitir NF">Separ.</dt><dd class="stock-overview__separated" id="stock-company-separated"><?php echo balanco_h(balanco_format_quantity($companySeparatedStock, 2)); ?></dd></div></dl></div>
        <div class="stock-overview__group stock-overview__group--location"><div class="stock-overview__title">Locação atual</div><dl class="stock-overview__metrics"><div><dt>Físico</dt><dd class="stock-overview__physical" id="stock-location-physical"><?php echo balanco_h(balanco_format_quantity($locationPhysicalStock, 2)); ?></dd></div><div><dt title="Pedidos">Ped.</dt><dd class="stock-overview__reserved" id="stock-location-orders"><?php echo balanco_h(balanco_format_quantity($locationOrderStock, 2)); ?></dd></div><div><dt title="Estoque físico menos pedidos">Líq.</dt><dd class="stock-overview__liquid" id="stock-location-liquid"><?php echo balanco_h(balanco_format_quantity($locationLiquidStock, 2)); ?></dd></div><div><dt title="Pedidos nos status Separando, Conferindo e Emitir NF">Separ.</dt><dd class="stock-overview__separated" id="stock-location-separated"><?php echo balanco_h(balanco_format_quantity($locationSeparatedStock, 2)); ?></dd></div></dl></div>
        <div class="stock-overview__group stock-overview__group--all-companies"><div class="stock-overview__title">Consolidado das empresas</div><dl class="stock-overview__metrics"><div><dt>Físico</dt><dd class="stock-overview__physical" id="stock-all-companies-physical">—</dd></div><div><dt title="Pedidos">Ped.</dt><dd class="stock-overview__reserved" id="stock-all-companies-orders">—</dd></div><div><dt title="Estoque físico menos pedidos">Líq.</dt><dd class="stock-overview__liquid" id="stock-all-companies-liquid">—</dd></div><div><dt title="Pedidos nos status Separando, Conferindo e Emitir NF">Separ.</dt><dd class="stock-overview__separated" id="stock-all-companies-separated">—</dd></div></dl></div>
