    <form method="post" id="finalize-balance"><input type="hidden" name="csrf" value="<?php echo balanco_h(balanco_csrf_token()); ?>"><input type="hidden" name="action" value="finalize_balance"><input type="hidden" name="quantity" id="finalize-quantity"></form>
