<script>var countInput=document.getElementById('counted-quantity'),dialog=document.getElementById('confirm-dialog'),abandonForm=document.getElementById('abandon-count'),abandonDialog=document.getElementById('abandon-dialog'),finalizeForm=document.getElementById('finalize-balance'),finalizeQuantity=document.getElementById('finalize-quantity'),confirmButton=document.getElementById('confirm-preview'),labelDialog=document.getElementById('label-dialog'),labelMessage=document.getElementById('label-dialog-message'),stockOverviewDialog=document.getElementById('stock-overview-dialog');function formatPreviewQuantity(value){var quantity=Number(String(value).replace(',','.'));return Number.isFinite(quantity)?quantity.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2}):value;}function openPreview(value){document.getElementById('confirm-quantity').textContent=formatPreviewQuantity(value);dialog.showModal();}document.getElementById('count-preview').addEventListener('submit',function(e){e.preventDefault();if(countInput.value===''){countInput.focus();return;}openPreview(countInput.value);});document.getElementById('use-current-stock').onclick=function(){countInput.value='<?php echo balanco_h($currentStock); ?>';countInput.focus();};document.getElementById('cancel-preview').onclick=function(){dialog.close();};confirmButton.onclick=function(){confirmButton.disabled=true;confirmButton.textContent='Efetivando…';finalizeQuantity.value=countInput.value;finalizeForm.submit();};abandonForm.addEventListener('submit',function(e){e.preventDefault();abandonDialog.showModal();});document.getElementById('cancel-abandon').onclick=function(){abandonDialog.close();};document.getElementById('confirm-abandon').onclick=function(){abandonForm.submit();};document.getElementById('open-label-print').onclick=function(){labelMessage.hidden=true;labelDialog.showModal();};document.getElementById('cancel-label').onclick=function(){labelDialog.close();countInput.focus();};labelDialog.addEventListener('close',function(){countInput.focus();});document.getElementById('open-stock-overview').onclick=function(){stockOverviewDialog.showModal();};document.getElementById('close-stock-overview').onclick=function(){stockOverviewDialog.close();};stockOverviewDialog.addEventListener('close',function(){countInput.focus();});document.querySelectorAll('[data-label-model]').forEach(function(button){button.onclick=function(){var form=document.createElement('form'),model=button.getAttribute('data-label-model');form.method='GET';form.action='<?php echo balanco_h(balanco_url('gerar_etiqueta.php')); ?>';form.target='_blank';form.style.display='none';[['t066_id','<?php echo (int) $id; ?>'],['model',model],['redirect','1']].forEach(function(field){var input=document.createElement('input');input.type='hidden';input.name=field[0];input.value=field[1];form.appendChild(input);});document.body.appendChild(form);form.submit();form.remove();labelDialog.close();};});</script>
<script>(function(){var form=document.getElementById('abandon-count'),modal=document.getElementById('abandon-dialog'),title=modal?modal.querySelector('h2'):null,message=modal?modal.querySelector('p'):null,defaultTitle=title?title.textContent:'',defaultMessage=message?message.innerHTML:'';if(!form||!modal||!window.history.pushState){return;}function restoreAbandonDialog(){if(title){title.textContent=defaultTitle;}if(message){message.innerHTML=defaultMessage;}}function confirmBrowserBack(){window.history.pushState({balancoCountActive:true},'',window.location.href);if(title){title.textContent='Existe uma contagem em andamento. Deseja abandonar a contagem?';}if(message){message.innerHTML='A locação <strong><?php echo balanco_h($item['D004_Local']); ?></strong> será liberada e ficará disponível para outro usuário realizar a contagem.';}if(!modal.open){modal.showModal();}}window.history.pushState({balancoCountActive:true},'',window.location.href);window.addEventListener('popstate',confirmBrowserBack);modal.addEventListener('close',restoreAbandonDialog);})();</script>
<script>(function(){var openButton=document.getElementById('open-stock-overview'),dialog=document.getElementById('stock-overview-dialog'),updated=document.getElementById('stock-overview-updated'),interval=null,url='<?php echo balanco_h(balanco_url('posicao-estoque.php?t066_id=' . (int) $id)); ?>';if(!openButton||!dialog||!window.fetch){return;}function setValue(id,value){var element=document.getElementById(id);if(element){element.textContent=value;}}function refresh(){updated.textContent='Atualizando posição…';return fetch(url,{credentials:'same-origin',cache:'no-store'}).then(function(response){if(!response.ok){throw new Error('Não foi possível atualizar a posição.');}return response.json();}).then(function(data){if(!data.ok){throw new Error(data.message||'Não foi possível atualizar a posição.');}setValue('stock-company-physical',data.company.physical);setValue('stock-company-orders',data.company.orders);setValue('stock-company-separated',data.company.separated);setValue('stock-company-liquid',data.company.liquid);setValue('stock-location-physical',data.location.physical);setValue('stock-location-orders',data.location.orders);setValue('stock-location-separated',data.location.separated);setValue('stock-location-liquid',data.location.liquid);setValue('stock-all-companies-physical',data.all_companies.physical);setValue('stock-all-companies-orders',data.all_companies.orders);setValue('stock-all-companies-separated',data.all_companies.separated);setValue('stock-all-companies-liquid',data.all_companies.liquid);setValue('stock-company-liquid-summary',data.company.liquid);setValue('stock-location-liquid-summary',data.location.liquid);updated.textContent='Atualizado às '+data.updated_at+'.';}).catch(function(error){updated.textContent=error.message;});}openButton.onclick=function(){dialog.showModal();refresh();if(interval===null){interval=window.setInterval(refresh,15000);}};dialog.addEventListener('close',function(){if(interval!==null){window.clearInterval(interval);interval=null;}countInput.focus();});})();</script>
<script>(function(){function applyLiquidTone(){document.querySelectorAll('[id^="stock-"][id*="liquid"]').forEach(function(element){var value=Number(element.textContent.trim().replace(/\./g,'').replace(',','.'));element.classList.toggle('stock-overview__negative',Number.isFinite(value)&&value<0);});}applyLiquidTone();var card=document.querySelector('.count-card');if(card&&window.MutationObserver){new MutationObserver(applyLiquidTone).observe(card,{subtree:true,childList:true,characterData:true});}})();</script>
